// Dicionário de apoio ao clique em palavras das Histórias (src/pages/Stories.jsx).
// Chave = forma normalizada (normalizeWord, de src/utils/storyTokenizer.js):
// minúscula, sem pontuação de borda, possessivo 's removido. Contrações de
// propósito ("don't", "it's") são preservadas inteiras — ver CONTRACTION_KEEP
// em storyTokenizer.js.
//
// Cada entrada tem exatamente 5 exemplos (não 1, como em words.js — words.js
// não serve para isto, é usado por 8+ jogos e tem seu próprio formato).
// stories.test.js confere que toda palavra usada em stories.js tem entrada
// aqui, e que toda entrada tem pt + 5 exemplos completos.
//
// ★ Palavras com MÚLTIPLOS SIGNIFICADOS nos exemplos (phrase varia a cada item):
//   call   → call, calls back, called off, calls for, calls out
//   get    → gets up, gets ready, gets back, get along, gets out
//   look   → looks for, look after, look out, look up, looks around
//   pick   → picks up, picks out, pick, pick on, picks up (aprender)
//   run    → run, runs away, run out, runs into, runs back
//   come   → come back, come over, came down, came across, come on
//   set    → set up, set out, sets the table, sets a goal, sets aside
//   make   → make a plan, make it, makes up, makes sense, makes
//   back   → back, calls back, gets back, back (atrás), come back
//   out    → out, out loud, out (porta), out (apagado), out (fora)
//   away   → away, away (guardado), away (fugindo), give away, far away
//   along  → brought along, get along, come along, along the way, along
//   brought→ brought up, brought along, brought, brought back, brought down
//   came   → came on, came back, came across, came down, came up
//   tell   → tell, tell apart, tell the truth, tell, tells off
//   way    → on the way, way back, by the way, way (muito), finds her way
//   broke  → broke away, broke, broke down, broke out, broke the record
//   fire   → fire, on fire, fired, fires, fires up
//   along  → brought along, get along, come along, along the way, along
//   sets   → sets, sets up, sets a goal, sets aside, sets (sol)
//   gets   → gets ready, gets up, gets out, gets back, gets to
//   picks  → picks up, picks out, picks, picks up (aprender), picks on
//   puts   → puts on, puts away, puts down, puts off, puts together
//   hangs  → hangs up, hangs, hang out, hang on, hang back
//   came   → came on, came back, came across, came down, came up
//   showed → showed up, showed, showed off, showed, showed

